export const SPEC_SCREEN_IDS: string[] = SPEC_SCREENS.map((s) => s.id);

export const SPEC_SCREEN_BY_ID: Record<string, SpecScreenNav> = SPEC_SCREENS.reduce(
  (acc, s) => { acc[s.id] = s; return acc; }, {} as Record<string, SpecScreenNav>);

export const SPEC_GROUP_BY_ID: Record<string, SpecGroup> = SPEC_GROUPS.reduce(
  (acc, g) => { acc[g.id] = g; return acc; }, {} as Record<string, SpecGroup>);

export const SPEC_ROLE_BY_KEY: Record<string, SpecRoleInfo> = SPEC_ROLES.reduce(
  (acc, r) => { acc[r.key] = r; return acc; }, {} as Record<string, SpecRoleInfo>);

export const SPEC_RULE_BY_ID: Record<string, SpecRule> = SPEC_RULES.reduce(
  (acc, r) => { acc[r.id] = r; return acc; }, {} as Record<string, SpecRule>);

/** 업무 그룹 → 소속 화면 id (MENU 1.3 순서) */
export function specGroupOfScreen(screenId: string): string {
  const s = SPEC_SCREEN_BY_ID[screenId];
  return s ? s.group : SPEC_GROUPS[0].id;
}
